y project, never an allocation.","tree":{"sha":"8ca9d49be8f7acf529818e2cb3f22833a12cc461","url":"https://api.github.com/repos/thebigbillz/baseline-planning-suite/git/trees/8ca9d49be8f7acf529818e2cb3f22833a12cc461"},"url":"https://api.github.com/repos/thebigbillz/baseline-planning-suite/git/commits/af83a8b14ebdb85b493c62d2ec2b4102063906e2","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/37770060?v=4","events_url":"https://api.github.com/users/thebigbillz/events{/privacy}","followers_url":"https://api.github.com/users/thebigbillz/followers","following_url":"https://api.github.com/users/thebigbillz/following{/other_user}","gists_url":"https://api.github.com/users/thebigbillz/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/thebigbillz","id":37770060,"login":"thebigbillz","node_id":"MDQ6VXNlcjM3NzcwMDYw","organizations_url":"https://api.github.com/users/thebigbillz/orgs","received_events_url":"https://api.github.com/users/thebigbillz/received_events","repos_url":"https://api.github.com/users/thebigbillz/repos","site_admin":false,"starred_url":"https://api.github.com/users/thebigbillz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/thebigbillz/subscriptions","type":"User","url":"https://api.github.com/users/thebigbillz","user_view_type":"public"},"html_url":"https://github.com/thebigbillz/baseline-planning-suite/commit/af83a8b14ebdb85b493c62d2ec2b4102063906e2","node_id":"C_kwDOUjgXP9oAKGFmODNhOGIxNGViZGI4NWI0OTNjNjJkMmVjMmI0MTAyMDYzOTA2ZTI","parents":[{"html_url":"https://github.com/thebigbillz/baseline-planning-suite/commit/147cec195ad821961c566a753ab1c03b10307259","sha":"147cec195ad821961c566a753ab1c03b10307259","url":"https://api.github.com/repos/thebigbillz/baseline-planning-suite/commits/147cec195ad821961c566a753ab1c03b10307259"}],"sha":"af83a8b14ebdb85b493c62d2ec2b4102063906e2","url":"https://api.gith